const OLLAMA_BASE_URL = process.env.REACT_APP_OLLAMA_BASE_URL || 'http://localhost:11434';
const OLLAMA_MODEL = process.env.REACT_APP_OLLAMA_MODEL || 'llama3';

export const ollamaService = {
  async sendMessage(message, options = {}) {
    try {
      const response = await fetch(`${OLLAMA_BASE_URL}/api/generate`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          //promp es el elemento mas importante: la instruccion que le damos al modelo, la pregunta y como se desea que responda
          model: OLLAMA_MODEL,
          prompt: `Eres un asistente universitario llamado TalkinPon. Responde de manera útil y concisa sobre temas administrativos universitarios.

          Contexto: El usuario está consultando sobre procesos administrativos universitarios.

          Pregunta: ${message}

          Responde de manera clara y directa, enfocándote en ayudar con trámites universitarios.`,
          stream: false,
          options: {
            temperature: 0.7,
            top_p: 0.9,
            ...options
          }
        })
      });

      if (!response.ok) throw new Error(`Error: ${response.status}`);
      const data = await response.json();
      return data.response;
    } catch (error) {
      console.error('Error calling Ollama:', error);
      throw error;
    }
  },

  async healthCheck() {
    try {
      const response = await fetch(`${OLLAMA_BASE_URL}/api/tags`);
      return response.ok;
    } catch (error) {
      return false;
    }
  }
};
